// The database's copy of the free-text scrubber's rules, so a Go test can compare it against the
// compiled Go copy in both directions — and, more usefully, run the same fixture corpus through
// both engines and fail when they disagree. Two regular-expression engines agreeing about a list
// is not something to assume.
func (q *Queries) PIIPatterns(ctx context.Context) ([]OpsPiiPattern, error) {
	rows, err := q.db.Query(ctx, pIIPatterns)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []OpsPiiPattern{}
	for rows.Next() {
		var i OpsPiiPattern
		if err := rows.Scan(
			&i.Kind,
			&i.Pattern,
			&i.Replacement,
			&i.DescriptionEn,
			&i.DescriptionBn,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

